import json

def demo_like_pattern(rows=17, cols=19):
    """
    Match the exact demo pattern structure.

    Demo pair 1 left 3 at output position (4,12):
    Row 0-1: all 0s
    Row 2: 5s at span 9-13 (center 12)
    Row 3: 2 at 9, 5 at 11, 2 at 13 (span 9-13)
    Row 4: 2 at 9, 3 at 12, 2 at 13 
    Row 5: 2 at 9, 2 at 13
    Row 6: 2 at edge, 8s middle, 2 at edge

    Top row of 5x5 = diamond_row - 3 + 1 = diamond_row - 2
    For diamond_row=4: top row = 2

    So for left diamond at col 7 with top row 1:
    diamond_row = 4 (3 + 1)
    """

    output = [[0]*cols for _ in range(rows)]

    # Left diamond centered at col 7
    diamond_row_left = 4  # row with 3 = 4
    diamond_col_left = 7

    for r, c in enumerate([]):
        pass

    # Build left diamond
    # Row 1 (diamond_row - 2): all 5s
    for c in range(diamond_col_left - 2, diamond_col_left + 3):
        output[1][c] = 5

    # Row 2 (diamond_row - 1): 2, 0, 5, 0, 2
    for c in range(diamond_col_left - 2, diamond_col_left + 3):
        if c == diamond_col_left:
            output[2][c] = 5
        elif c in [diamond_col_left-2, diamond_col_left+2]:
            output[2][c] = 2
        else:
            output[2][c] = 0  # actually demo has 0 here, but I think we just have 5 or 2

    # Row 3 (diamond_row): 2, 0, 3, 0, 2
    for c in range(diamond_col_left - 2, diamond_col_left + 3):
        if c == diamond_col_left:
            output[3][c] = 3
        elif c in [diamond_col_left-2, diamond_col_left+2]:
            output[3][c] = 2
        else:
            output[3][c] = 0

    # Row 4: 2 at edges, rest 2
    for c in range(diamond_col_left - 2, diamond_col_left + 3):
        output[4][c] = 2

    # Right diamond centered at col 11
    diamond_row_right = 7  # based on my earlier calculation
    diamond_col_right = 11

    # Row 5 (diamond_row - 2): all 5s
    for c in range(diamond_col_right - 2, diamond_col_right + 3):
        output[5][c] = 5

    # Row 6: 2, 0, 5, 0, 2
    for c in range(diamond_col_right - 2, diamond_col_right + 3):
        if c == diamond_col_right:
            output[6][c] = 5
        elif c in [diamond_col_right-2, diamond_col_right+2]:
            output[6][c] = 2
        else:
            output[6][c] = 0

    # Row 7: 2, 0, 3, 0, 2
    for c in range(diamond_col_right - 2, diamond_col_right + 3):
        if c == diamond_col_right:
            output[7][c] = 3
        elif c in [diamond_col_right-2, diamond_col_right+2]:
            output[7][c] = 2
        else:
            output[7][c] = 0

    # Row 8: all 2s in span
    for c in range(diamond_col_right - 2, diamond_col_right + 3):
        output[8][c] = 2

    # Connector at row 6 (between diamonds at rows 4 and 7)
    connector_row = 6

    for c in range(cols):
        if output[connector_row][c] == 0:
            output[connector_row][c] = 8

    # Fill remaining with 8s
    for r in range(rows):
        for c in range(cols):
            if output[r][c] == 0:
                output[r][c] = 8

    return output

